alter table public.simulation_runs alter column user_id drop not null;
alter table public.simulation_runs add column if not exists run_scope text not null default 'USER' check(run_scope in('USER','SYSTEM_RESEARCH')), add column if not exists engine_version text, add column if not exists qualification_policy_version text, add column if not exists paper_policy_version text, add column if not exists fee_model_version text, add column if not exists slippage_model_version text, add column if not exists fx_policy_version text, add column if not exists information_cutoff_policy text, add column if not exists candidate_dataset_hash text, add column if not exists market_dataset_hash text, add column if not exists input_hash text unique, add column if not exists currency text not null default 'SEK';
alter table public.simulation_trades alter column signal_id drop not null;
alter table public.simulation_trades add column if not exists candidate_id uuid references public.jackpot_candidates(id), add column if not exists candidate_revision integer, add column if not exists qualification_evaluation_id uuid references public.qualification_evaluations(id), add column if not exists execution_status text, add column if not exists execution_reason text, add column if not exists evidence_refs jsonb not null default '[]';
create table if not exists public.simulation_candidate_evaluations(id uuid primary key default gen_random_uuid(),simulation_run_id uuid not null references public.simulation_runs(id),candidate_id uuid not null references public.jackpot_candidates(id),candidate_revision integer not null,policy_version text not null,information_cutoff_at timestamptz not null,status text not null,reason text not null,blocker_codes jsonb not null default'[]',known_inputs jsonb not null default'{}',evidence_refs jsonb not null default'[]',input_hash text not null,created_at timestamptz not null default now(),unique(simulation_run_id,candidate_id,policy_version));
alter table public.simulation_results add column if not exists data_status text not null default 'INSUFFICIENT_DATA',add column if not exists fees_sek numeric not null default 0,add column if not exists slippage_sek numeric not null default 0,add column if not exists diagnostics jsonb not null default'{}',add column if not exists attribution jsonb not null default'{}';
alter table public.simulation_results alter column max_drawdown_percent drop not null;
alter table public.simulation_candidate_evaluations enable row level security;
create policy "public read system simulations" on public.simulation_runs for select using(run_scope='SYSTEM_RESEARCH');
create policy "public read simulation evaluations" on public.simulation_candidate_evaluations for select using(exists(select 1 from public.simulation_runs r where r.id=simulation_run_id and r.run_scope='SYSTEM_RESEARCH'));
grant select on public.simulation_candidate_evaluations to anon,authenticated; grant all on public.simulation_candidate_evaluations to service_role;
create or replace function public.prevent_simulation_child_mutation() returns trigger language plpgsql as $$begin raise exception 'Simulation records are immutable';end$$;
create trigger simulation_evaluations_immutable before update or delete on public.simulation_candidate_evaluations for each row execute function public.prevent_simulation_child_mutation();
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation'));
